// dropIgnored returns the specs git does not ignore, in order. Tracked paths
// are never reported ignored by check-ignore, so a tracked chunk still stages.
func dropIgnored(repoRoot string, specs []string) ([]string, error) {
	args := append([]string{"check-ignore", "-z", "--"}, specs...)
	out, err := gitRun(repoRoot, "git check-ignore", args...)
	if err != nil {
		var ee *exec.ExitError
		if errors.As(err, &ee) && ee.ExitCode() == 1 {
			return specs, nil // exit 1: no path is ignored
		}
		return nil, err
	}
	ignored := make(map[string]bool)
	for _, t := range bytes.Split(out, []byte{0}) {
		if len(t) > 0 {
			ignored[string(t)] = true
		}
	}
	kept := make([]string, 0, len(specs))
	skipped := ""
	for _, s := range specs {
		if ignored[s] {
			skipped = s
			continue
		}
		kept = append(kept, s)
	}
	if skipped != "" {
		ignoreNote.Do(func() {
			fmt.Fprintf(ignoreNoteOut, "ethos: not staging %s: this repo gitignores it, so its audit stays local\\n", skipped)
		})
	}
	return kept, nil
}

